  // Same type within 50 cm is one item, as the app shows it (the radius is our guess).
  const groups=[];for(const o of list){const near=g=>g.label===o.etykieta&&g.nazwa===(o.nazwa||'Obstacle')&&o.x!=null&&o.y!=null&&g.x!=null&&g.y!=null&&Math.hypot(g.x-o.x,g.y-o.y)<=8;const g=groups.find(near);
   if(g){g.items.push(o);g.x=(g.x*(g.items.length-1)+o.x)/g.items.length;g.y=(g.y*(g.items.length-1)+o.y)/g.items.length;}else groups.push({label:o.etykieta,nazwa:o.nazwa||'Obstacle',x:o.x??null,y:o.y??null,items:[o]});}
  return groups;
